create table eba_demo_load_sales (
    id             number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    region         varchar2(255 byte),
    country        varchar2(255 byte),
    item_type      varchar2(50 byte),
    sales_channel  varchar2(50 byte),
    order_priority varchar2(1 byte),
    order_date     date,
    order_id       number,
    ship_date      date,
    units_sold     number,
    unit_price     number,
    unit_cost      number,
    total_revenue  number,
    total_cost     number,
    total_profit   number,
    created        date,
    last_updated   date
);

alter table eba_demo_load_sales add primary key ( id )
    using index enable;

